CREATE TABLE posting (id INTEGER NOT NULL, jurnal_id INTEGER NOT NULL, buku_id INTEGER NOT NULL, jumlah INTEGER NOT NULL, dibuat TEXT NOT NULL, PRIMARY KEY (id, dibuat));
WITH RECURSIVE g(x) AS (SELECT 1 UNION ALL SELECT x + 1 FROM g WHERE x < 120000)
INSERT INTO posting SELECT x, 1 + x / 2, 1 + (x % 1000), CASE WHEN x % 2 = 0 THEN -25000 ELSE 25000 END, datetime(date('2026-01-01', '+' || ((x - 1) / 10000) || ' months'), '+' || (((x - 1) % 10000) * 200) || ' seconds') FROM g;

